/* =====================================================================
   FIREBASE INIT + FIRESTORE DATA LAYER
   ===================================================================== */
firebase.initializeApp(CONFIG.FIREBASE_CONFIG);
const fbAuth = firebase.auth();
const fbDb = firebase.firestore();
// Persistent sessions: now that this runs on raqeem.qd.je (a real hosted
// domain, not Claude's in-chat preview), Firebase can safely use LOCAL
// persistence — the student stays signed in across visits/tabs until they
// explicitly log out via the dashboard.
fbAuth.setPersistence(firebase.auth.Auth.Persistence.LOCAL).catch(err => console.error(err));

/* Lightweight in-memory cache for content that rarely changes mid-session
   (tracks/courses/lectures/tasks) — makes repeat navigation feel instant
   instead of re-fetching Firestore on every page. Writes below invalidate
   the relevant cache entries automatically, so admin edits still show up
   within a minute (or immediately after any write to that collection). */
const _dbCache = new Map();
const CACHEABLE = new Set(['Tracks','Courses','Lectures','Tasks']);
const CACHE_TTL_MS = 60000;
function _invalidateCache(collection){
  for (const key of _dbCache.keys()) if (key.startsWith(collection+'|')) _dbCache.delete(key);
}
function stripUndefined(obj){
  // Firestore rejects `undefined` field values outright (throws a client-side
  // 'invalid-argument' error) — this keeps that from ever reaching the SDK,
  // regardless of which call site forgot to guard a value.
  const out = {};
  for (const k in obj) if (obj[k] !== undefined) out[k] = obj[k];
  return out;
}
const DB = {
  async listAll(collection, whereField, whereValue){
    const cacheKey = `${collection}|${whereField||''}|${whereValue||''}`;
    if (CACHEABLE.has(collection)){
      const cached = _dbCache.get(cacheKey);
      if (cached && (Date.now()-cached.ts) < CACHE_TTL_MS) return cached.data;
    }
    try {
      let ref = fbDb.collection(collection);
      if (whereField) ref = ref.where(whereField, '==', whereValue);
      const snap = await ref.get();
      const data = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      if (CACHEABLE.has(collection)) _dbCache.set(cacheKey, { data, ts: Date.now() });
      return data;
    } catch (e) {
      e.collection = collection;
      throw e;
    }
  },
  async get(collection, id){
    try {
      const doc = await fbDb.collection(collection).doc(id).get();
      return doc.exists ? { id: doc.id, ...doc.data() } : null;
    } catch (e) {
      e.collection = collection;
      throw e;
    }
  },
  async create(collection, data, id){
    try {
      _invalidateCache(collection);
      const clean = stripUndefined(data);
      if (id) { await fbDb.collection(collection).doc(id).set(clean); return { id }; }
      const ref = await fbDb.collection(collection).add(clean);
      return { id: ref.id };
    } catch (e) {
      e.collection = collection;
      throw e;
    }
  },
  async update(collection, id, patch){
    try {
      await fbDb.collection(collection).doc(id).set(stripUndefined(patch), { merge: true });
      return { id };
    } catch (e) {
      e.collection = collection;
      throw e;
    }
  },
};
function dbFriendlyError(e){
  const code = e && (e.code || '');
  if (code === 'auth/email-already-in-use') return 'هذا البريد مسجّل بحساب بالفعل';
  if (code === 'auth/invalid-email') return 'صيغة البريد الإلكتروني غير صحيحة';
  if (code === 'auth/weak-password') return 'كلمة المرور ضعيفة، استخدم ٨ خانات على الأقل';
  if (code === 'auth/wrong-password' || code === 'auth/invalid-credential') return 'بيانات الدخول غير صحيحة';
  if (code === 'auth/user-not-found') return 'لا يوجد حساب بهذه البيانات';
  if (code === 'auth/popup-closed-by-user') return 'تم إغلاق نافذة تسجيل الدخول عبر جوجل قبل إتمامها';
  if (code === 'auth/popup-blocked') return 'المتصفح منع نافذة جوجل المنبثقة — اسمح بالنوافذ المنبثقة لهذا الموقع';
  if (code === 'auth/unauthorized-domain') return 'هذا الدومين غير مصرّح له بتسجيل الدخول — أضِفه في Firebase Authentication ← Settings ← Authorized domains';
  if (code === 'auth/operation-not-allowed') return 'طريقة الدخول دي غير مفعّلة في مشروع Firebase — فعّلها من Authentication ← Sign-in method';
  if (code === 'auth/configuration-not-found' || code === 'auth/invalid-api-key') return 'إعدادات Firebase غير صحيحة أو خدمة Authentication غير مفعّلة في المشروع أصلًا';
  if (code === 'auth/network-request-failed') return 'تعذّر الوصول للإنترنت أثناء تسجيل الدخول';
  if (code === 'permission-denied') return `لا يوجد صلاحية وصول لمجموعة "${e.collection || ''}" — تحقّق من قواعد الأمان (Firestore Rules)`;
  if (code === 'not-found' || code === 'failed-precondition') return `قاعدة بيانات Firestore غير موجودة لهذا المشروع بعد — أنشئها من Firebase Console ← Firestore Database ← Create database${e.collection ? ' (مجموعة: '+e.collection+')' : ''}`;
  if (code === 'unavailable' || (e && e.message && e.message.includes('Failed to fetch'))) return 'تعذّر الوصول للإنترنت أو لخدمة Firebase، تحقق من الاتصال';
  console.error(e);
  // fallback: show the raw code/message so it can be reported back for diagnosis
  return `خطأ غير متعرَّف عليه: ${code || (e && e.message) || 'غير معروف'}`;
}
async function sha256Hex(text){
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
}
const ImgBB = {
  async upload(file){
    const fd = new FormData(); fd.append('image', file);
    const res = await fetch(`https://api.imgbb.com/1/upload?key=${CONFIG.IMGBB_KEY}`, { method:'POST', body:fd });
    const json = await res.json();
    if (!json.success) throw new Error('ImgBB upload failed');
    return json.data.url;
  }
};
function safeError(msg){ console.error(msg); return 'حدث خطأ، حاول مرة أخرى.'; }
function toast(msg){
  const t = document.getElementById('toast');
  t.innerHTML = `${icon('check')}<span>${msg}</span>`;
  t.classList.add('show');
  clearTimeout(t._timer);
  t._timer = setTimeout(() => t.classList.remove('show'), 2800);
}
function escapeHtml(s){ return String(s ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])); }
/* ---- Custom-styled dropdown (native <select> menus are OS-rendered and
   can't be restyled — this replaces them with an app-styled equivalent) ---- */
function cselectHtml(id, options, selected){
  const sel = selected || options[0].value;
  const selLabel = (options.find(o=>o.value===sel)||options[0]).label;
  return `<div class="cselect" id="${id}" data-value="${escapeHtml(sel)}">
    <button type="button" class="cselect-trigger"><span class="cselect-label">${escapeHtml(selLabel)}</span>${icon('chevron')}</button>
    <div class="cselect-menu">${options.map(o=>`<div class="cselect-opt ${o.value===sel?'active':''}" data-value="${escapeHtml(o.value)}">${escapeHtml(o.label)}</div>`).join('')}</div>
  </div>`;
}
function cselectValue(id){ return document.getElementById(id)?.dataset.value || ''; }
function cselectSetValue(id, val){
  const el = document.getElementById(id); if (!el) return;
  el.dataset.value = val;
  const opt = el.querySelector(`.cselect-opt[data-value="${val}"]`);
  el.querySelectorAll('.cselect-opt').forEach(o=>o.classList.toggle('active', o.dataset.value===val));
  if (opt) el.querySelector('.cselect-label').textContent = opt.textContent;
}
function initCustomSelects(root){
  (root||document).querySelectorAll('.cselect').forEach(el=>{
    if (el._csInit) return; el._csInit = true;
    const trigger = el.querySelector('.cselect-trigger');
    const menu = el.querySelector('.cselect-menu');
    trigger.addEventListener('click', (e)=>{
      e.stopPropagation();
      document.querySelectorAll('.cselect-menu.open').forEach(m=>{ if (m!==menu) m.classList.remove('open'); });
      menu.classList.toggle('open');
    });
    el.querySelectorAll('.cselect-opt').forEach(opt=>{
      opt.addEventListener('click', ()=>{
        cselectSetValue(el.id, opt.dataset.value);
        menu.classList.remove('open');
        el.dispatchEvent(new Event('cselect-change'));
      });
    });
  });
}
document.addEventListener('click', ()=> document.querySelectorAll('.cselect-menu.open').forEach(m=>m.classList.remove('open')));
/* Basic client-side guard against abusive reviews — catches common cases,
   not a substitute for the admin's own moderation (Reviews tab still lets
   the admin delete anything that slips through). */
function isLikelyEnglish(text){
  if (!text) return false;
  const arabicChars = (text.match(/[\u0600-\u06FF]/g) || []).length;
  const latinChars = (text.match(/[A-Za-z]/g) || []).length;
  return latinChars > arabicChars;
}
function containsAbusiveLanguage(text){
  if (!text) return false;
  const normalized = text
    .toLowerCase()
    .replace(/[إأآا]/g, 'ا')
    .replace(/[ة]/g, 'ه')
    .replace(/[ىي]/g, 'ي')
    .replace(/[^a-z\u0600-\u06FF0-9\s]/g, '');
  const blockedTerms = [
    'كسم','خول','منيوك','عرص','قحبه','شرموطه','كلب ابن','ابن كلب','متناك','زبي','طيز',
    'fuck','shit','bitch','asshole','bastard','slut','whore','cunt','dick','faggot','nigger','retard',
  ];
  return blockedTerms.some(term => normalized.includes(term));
}
function getYouTubeEmbedUrl(url){
  if (!url) return null;
  try {
    const u = new URL(url);
    const host = u.hostname.replace(/^www\./, '');
    let videoId = null;
    if (host === 'youtu.be') {
      videoId = u.pathname.slice(1);
    } else if (host === 'youtube.com' || host === 'm.youtube.com' || host === 'music.youtube.com') {
      if (u.pathname === '/watch') videoId = u.searchParams.get('v');
      else if (u.pathname.startsWith('/shorts/')) videoId = u.pathname.split('/')[2];
      else if (u.pathname.startsWith('/embed/')) videoId = u.pathname.split('/')[2];
      else if (u.pathname.startsWith('/live/')) videoId = u.pathname.split('/')[2];
    } else {
      return null;
    }
    if (!videoId) return null;
    const start = u.searchParams.get('t') || u.searchParams.get('start');
    const startParam = start ? `&start=${parseInt(start,10)||0}` : '';
    return `https://www.youtube-nocookie.com/embed/${videoId}?rel=0${startParam}`;
  } catch(e){ return null; }
}
function genReferralCode(uid){ return `RQM-${String(uid).replace(/[^a-zA-Z0-9]/g,'').slice(0,6).toUpperCase()}`; }
function copyText(text){
  navigator.clipboard?.writeText(text).then(()=>toast('تم النسخ')).catch(()=>toast('تعذّر النسخ'));
}

