/* =====================================================================
   Feature 1: NOTIFICATIONS — live (Firestore onSnapshot instead of a
   one-time fetch), so a new notification shows up the instant it's
   written, with no refresh/poll needed. While the tab is open we also
   pop an in-app toast and, if the student has granted permission, a
   real desktop notification.
   NOTE: this is "instant while the app is open", not true push — actual
   push delivery to a closed browser needs a server (Firebase Cloud
   Messaging + a backend to trigger it), which this static front-end
   doesn't have. ---- */
const notifPanel = document.getElementById('notifPanel');
document.getElementById('notifBtn').addEventListener('click', () => {
  notifPanel.classList.toggle('show');
  if (notifPanel.classList.contains('show')) markAllNotificationsRead();
});
document.addEventListener('click', (e) => {
  if (!notifPanel.contains(e.target) && e.target.id !== 'notifBtn' && !document.getElementById('notifBtn').contains(e.target)) {
    notifPanel.classList.remove('show');
  }
});
let _notifUnsub = null;
let _notifSeenIds = null; // null = first snapshot for this session, not "no notifications yet"
function renderNotifItems(sorted){
  const unread = sorted.filter(n=>String(n.read).toUpperCase()!=='TRUE').length;
  const badge = document.getElementById('notifBadge');
  if (badge) {
    const wasHidden = badge.style.display === 'none' || !badge.style.display;
    badge.style.display = unread ? 'flex' : 'none';
    badge.textContent = unread>9?'9+':unread;
    if (unread && wasHidden) badge.classList.add('pop-celebrate');
  }
  notifPanel.innerHTML = sorted.length ? sorted.slice(0,20).map(n => `
    <div class="notif-item ${String(n.read).toUpperCase()!=='TRUE'?'unread':''}" onclick="${n.link?`navigate('${n.link}')`:''}">
      <strong>${escapeHtml(n.title||'')}</strong>
      <span>${escapeHtml(n.message||'')} · ${escapeHtml((n.created_at||'').slice(0,10))}</span>
    </div>`).join('') : `<div class="notif-item" style="text-align:center; color:var(--ink-soft);">لا توجد إشعارات</div>`;
}
function subscribeNotifications(){
  if (_notifUnsub) { _notifUnsub(); _notifUnsub = null; }
  if (!session.user) return;
  _notifSeenIds = null;
  try {
    _notifUnsub = fbDb.collection('Notifications').where('user_id','==',session.user.uid)
      .onSnapshot(snap => {
        const items = snap.docs.map(d => ({ id:d.id, ...d.data() }));
        const sorted = items.sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||''));
        // announce anything genuinely new (present now, wasn't in the last snapshot)
        if (_notifSeenIds) {
          const fresh = sorted.filter(n => !_notifSeenIds.has(n.id) && String(n.read).toUpperCase()!=='TRUE');
          fresh.forEach(n => announceNotification(n));
        }
        _notifSeenIds = new Set(sorted.map(n=>n.id));
        renderNotifItems(sorted);
      }, err => console.error(err));
  } catch(e){ console.error(e); }
}
function announceNotification(n){
  toast(`${icon('bell')} ${n.title||'إشعار جديد'}`);
  try {
    if (typeof Notification !== 'undefined' && Notification.permission === 'granted' && document.hidden) {
      new Notification(n.title || 'سرمد', { body: n.message||'', icon: BRAND_ICON_192 });
    }
  } catch(e){ /* Notification API unavailable/blocked — the in-app toast above still covers it */ }
}
function requestNotificationPermission(){
  try { if (typeof Notification !== 'undefined' && Notification.permission === 'default') Notification.requestPermission(); }
  catch(e){ /* no-op */ }
}
async function markAllNotificationsRead(){
  if (!session.user) return;
  try {
    const items = await DB.listAll('Notifications', 'user_id', session.user.uid);
    const unread = items.filter(n=>String(n.read).toUpperCase()!=='TRUE');
    await Promise.all(unread.map(n => DB.update('Notifications', n.id, { read:'TRUE' })));
    const badge = document.getElementById('notifBadge');
    if (badge) badge.style.display = 'none';
  } catch(e){ console.error(e); }
}
async function notifyUser(uid, title, message, link){
  try { await DB.create('Notifications', { user_id:uid, title, message, link:link||'', read:'FALSE', created_at:new Date().toISOString() }); }
  catch(e){ console.error(e); }
}

