document.getElementById('forgotBtn').addEventListener('click', () => {
  const prefill = document.getElementById('loginEmail').value.trim();
  openForgotPasswordModal(prefill);
});
function openForgotPasswordModal(prefillEmail){
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay open';
  overlay.innerHTML = `<div class="modal">
    <div class="modal-head"><h2>استعادة كلمة المرور</h2><button class="modal-close" id="fpModalClose">✕</button></div>
    <div class="field"><label>البريد الإلكتروني</label><input type="email" id="fpEmailInput" value="${escapeHtml(prefillEmail||'')}" placeholder="name@example.com"></div>
    <p style="font-size:12.5px; color:var(--ink-soft); margin-bottom:16px;">هنبعتلك رابط لإعادة تعيين كلمة المرور على البريد ده.</p>
    <button class="btn btn-primary btn-block" id="fpSubmitBtn">إرسال الرابط</button>
  </div>`;
  document.body.appendChild(overlay);
  const close = () => overlay.remove();
  overlay.addEventListener('click', e => { if (e.target===overlay) close(); });
  overlay.querySelector('#fpModalClose').addEventListener('click', close);
  overlay.querySelector('#fpSubmitBtn').addEventListener('click', async () => {
    const email = overlay.querySelector('#fpEmailInput').value.trim();
    if (!email){ toast('اكتب بريدك الإلكتروني أولًا'); return; }
    const btn = overlay.querySelector('#fpSubmitBtn');
    btn.disabled = true; btn.textContent = '...جارٍ الإرسال';
    try {
      if (!RateGuard.canSendEmail()) { toast(emailLimitMessage()); btn.disabled=false; btn.textContent='إرسال الرابط'; return; }
      await fbAuth.sendPasswordResetEmail(email);
      RateGuard.recordEmail();
      toast('تم إرسال رابط استعادة كلمة المرور إلى بريدك الإلكتروني');
      close();
    } catch(e){ toast(dbFriendlyError(e)); btn.disabled=false; btn.textContent='إرسال الرابط'; }
  });
}

function userIsProfileComplete(u){
  return !!(u && u.full_name && u.phone && u.gender && u.level);
}
function sessionFromUserRow(uid, row, emailVerified){
  return {
    uid, name: row.full_name, nameEn: row.full_name_en, email: row.email, phone: row.phone, gender: row.gender,
    level: row.level, avatar: row.avatar_url, referral_code: row.referral_code || genReferralCode(uid),
    profileComplete: userIsProfileComplete(row),
    emailVerified: emailVerified !== false,
    banned: !!row.banned, ban_reason: row.ban_reason || '',
  };
}
async function loadUserDoc(uid){
  const row = await DB.get('Users', uid);
  return row;
}

document.getElementById('loginSubmit').addEventListener('click', async () => {
  const btn = document.getElementById('loginSubmit');
  const errEl = document.getElementById('loginErr'); errEl.style.display='none';
  const isEmailMode = document.querySelector('[data-login].active').dataset.login === 'email';
  const identifier = isEmailMode ? document.getElementById('loginEmail').value.trim() : document.getElementById('loginPhone').value.trim();
  const pass = document.getElementById('loginPassword').value;
  if (!identifier || !pass){ errEl.textContent='أدخل بيانات الدخول كاملة'; errEl.style.display='block'; return; }
  btn.textContent='...جارٍ الدخول'; btn.disabled=true;
  try {
    let email = identifier;
    if (!isEmailMode) {
      // phone login: resolve the matching account's email first, then sign in
      // with Firebase Auth (which is keyed by email, not phone, in this setup)
      const matches = await DB.listAll('Users', 'phone', identifier);
      if (!matches.length){ errEl.textContent='لا يوجد حساب بهذا الرقم'; errEl.style.display='block'; noteAuthFailure(); return; }
      email = matches[0].email;
    }
    const cred = await fbAuth.signInWithEmailAndPassword(email, pass);
    const row = await loadUserDoc(cred.user.uid);
    RateGuard.clearFails();
    session.user = sessionFromUserRow(cred.user.uid, row || {}, cred.user.emailVerified);
    renderNavForUser(); closeAuth(); toast('تم تسجيل الدخول بنجاح'); router();
  } catch(e){ errEl.textContent = dbFriendlyError(e); errEl.style.display='block'; noteAuthFailure(); }
  finally { btn.textContent='دخول'; btn.disabled=false; }
});

document.getElementById('signupSubmit').addEventListener('click', async () => {
  const btn = document.getElementById('signupSubmit');
  const passErr = document.getElementById('suPassErr'); passErr.style.display='none';
  const name = document.getElementById('suName').value.trim();
  const email = document.getElementById('suEmail').value.trim();
  const pass = document.getElementById('suPass').value;
  const pass2 = document.getElementById('suPass2').value;
  const passOk = pass.length>=8 && /[0-9]/.test(pass) && /[a-zA-Z]/.test(pass);
  if (!name || name.trim().split(/\s+/).length<3){ toast('الرجاء إدخال الاسم الثلاثي كاملًا'); return; }
  if (!email){ toast('الرجاء إدخال البريد الإلكتروني'); return; }
  if (!document.getElementById('suAgree').checked){ toast('يجب الموافقة على الشروط والخصوصية أولًا'); return; }
  if (!passOk || pass!==pass2){ passErr.style.display='block'; return; }
  btn.textContent='...جارٍ الإنشاء'; btn.disabled=true;
  try {
    const cred = await fbAuth.createUserWithEmailAndPassword(email, pass);
    let avatarUrl='';
    const file = document.getElementById('suAvatar').files[0];
    if (file) avatarUrl = await ImgBB.upload(file);
    const row = {
      full_name:name, full_name_en: document.getElementById('suNameEn').value.trim(), email,
      phone:document.getElementById('suPhone').value.trim(),
      gender:document.querySelector('[data-gender].active').dataset.gender,
      level: cselectValue('suLevel'),
      avatar_url:avatarUrl, role:'student', created_at:new Date().toISOString(),
      referral_code: genReferralCode(cred.user.uid),
    };
    await DB.create('Users', row, cred.user.uid);
    // Feature 4: referral program — if a referral code was entered, link the
    // two accounts and notify whoever referred this new student.
    const referralInput = document.getElementById('suReferral').value.trim().toUpperCase();
    if (referralInput) {
      try {
        const referrers = await DB.listAll('Users', 'referral_code', referralInput);
        if (referrers.length) {
          const referrer = referrers[0];
          await DB.create('Referrals', { referrer_uid: referrer.id, new_user_uid: cred.user.uid, new_user_name: name, created_at: new Date().toISOString() });
          notifyUser(referrer.id, 'دعوة ناجحة', `${name} انضم إلى سرمد عبر رابط دعوتك`, 'dashboard');
        }
      } catch(e){ console.error(e); }
    }
    session.user = sessionFromUserRow(cred.user.uid, row, cred.user.emailVerified);
    // Real Firebase email verification — sends the actual confirmation
    // email through Firebase's own mail service.
    try { if (RateGuard.canSendEmail()) { await cred.user.sendEmailVerification(); RateGuard.recordEmail(); } } catch(e){ console.error(e); }
    renderNavForUser(); closeAuth();
    toast('تم إنشاء الحساب — تحقق من بريدك الإلكتروني لتفعيل حسابك');
    router();
  } catch(e){ toast(dbFriendlyError(e)); noteAuthFailure(); }
  finally { btn.textContent='إنشاء الحساب'; btn.disabled=false; }
});

/* ---- Real Google Sign-In (Firebase Auth Google provider, popup flow) ----
   Requires the domain this file is hosted on to be listed under Firebase
   Console → Authentication → Settings → Authorized domains. It will NOT
   work opened as a local file (file:// or content://) — Firebase rejects
   unregistered origins. Host it on your real domain to test this button. */
document.getElementById('googleBtn').addEventListener('click', async () => {
  try {
    const provider = new firebase.auth.GoogleAuthProvider();
    const cred = await fbAuth.signInWithPopup(provider);
    let row = await loadUserDoc(cred.user.uid);
    if (!row) {
      row = {
        full_name: cred.user.displayName || '', email: cred.user.email || '',
        phone:'', gender:'', level:'', avatar_url: cred.user.photoURL || '',
        role:'student', created_at:new Date().toISOString(),
        referral_code: genReferralCode(cred.user.uid),
      };
      await DB.create('Users', row, cred.user.uid);
    }
    session.user = sessionFromUserRow(cred.user.uid, row, cred.user.emailVerified);
    renderNavForUser(); closeAuth();
    if (!session.user.profileComplete) {
      // mandatory now — the modal has no close button and no backdrop-dismiss,
      // so the student must finish these fields before doing anything else.
      document.getElementById('completeOverlay').classList.add('open');
      toast('أكمل بياناتك للمتابعة');
    } else {
      toast('تم تسجيل الدخول بنجاح');
    }
    router();
  } catch(e){ toast(dbFriendlyError(e)); }
});
document.getElementById('completeSubmit').addEventListener('click', async () => {
  const btn = document.getElementById('completeSubmit');
  const name = document.getElementById('cpName').value.trim();
  if (!name || name.trim().split(/\s+/).length<3){ toast('الاسم الثلاثي مطلوب'); return; }
  const patch = {
    full_name: name,
    phone: document.getElementById('cpPhone').value.trim(),
    gender: document.querySelector('[data-cgender].active').dataset.cgender,
    level: cselectValue('cpLevel'),
  };
  btn.textContent='...جارٍ الحفظ'; btn.disabled=true;
  try {
    if (session.user?.uid) await DB.update('Users', session.user.uid, patch);
    Object.assign(session.user, patch, { profileComplete:true });
    document.getElementById('completeOverlay').classList.remove('open');
    toast('تم حفظ بياناتك'); router();
  } catch(e){ toast(dbFriendlyError(e)); }
  finally { btn.textContent='حفظ ومتابعة'; btn.disabled=false; }
});
let _authResolved = false;
fbAuth.onAuthStateChanged(async (user) => {
  // Keeps the in-memory session in sync with Firebase's own auth state —
  // this is also what restores a persisted session on page load/reopen
  // (LOCAL persistence), so the student doesn't have to sign in every visit.
  // This handler also does double duty as the app's FIRST real render: since
  // login is mandatory now, we hold off rendering anything at all until this
  // fires at least once (see the INIT block below), whether that resolves to
  // a guest or a restored session, rather than guessing and re-rendering.
  if (!user) {
    if (session.user) { session.user = null; _watermarkBuilt = false; renderNavForUser(); }
    if (!_authResolved) { _authResolved = true; router(); }
    return;
  }
  if (session.user && session.user.uid === user.uid) return;
  try {
    const row = await loadUserDoc(user.uid);
    if (row) {
      session.user = sessionFromUserRow(user.uid, row, user.emailVerified);
      renderNavForUser();
      // re-render the current route so auth-gated views (dashboard, payment)
      // reflect the restored session instead of the logged-out state they
      // may have already rendered before this async check resolved.
      router();
    }
  } catch(e){ console.error(e); }
  finally { _authResolved = true; }
});
function requireCompleteProfile(next){
  if (!session.user){ openAuth('login'); return false; }
  if (!session.user.profileComplete){ document.getElementById('completeOverlay').classList.add('open'); return false; }
  next && next(); return true;
}

