/* Historical note: the "المسارات" nav link used to be a same-page anchor
   scroll combined with a data-route override, which caused a hash race
   (see git history) — it's now a real #/tracks route instead, so no special
   handling is needed here anymore. */

/* ---- Mobile page-list (hamburger) menu ---- */
const mobileMenu = document.getElementById('mobileMenu');
document.getElementById('menuToggle').addEventListener('click', () => mobileMenu.classList.toggle('open'));
document.querySelectorAll('[data-close-menu]').forEach(el => el.addEventListener('click', () => mobileMenu.classList.remove('open')));
window.addEventListener('hashchange', () => mobileMenu.classList.remove('open'));

/* ---- Smoothness: thin top progress bar + fade-in for every route change.
   Purely additive — it watches appRoot for content swaps instead of having
   to touch every render*() function, so nothing existing changes. ---- */
const topLoader = document.getElementById('topLoader');
function startTopLoader(){
  topLoader.style.transition = 'none';
  topLoader.style.width = '0%';
  topLoader.style.opacity = '1';
  void topLoader.offsetWidth; // force reflow so the next transition actually animates
  topLoader.style.transition = 'width .5s cubic-bezier(.2,.7,.3,1), opacity .25s ease';
  topLoader.style.width = '72%';
}
function doneTopLoader(){
  topLoader.style.width = '100%';
  setTimeout(() => { topLoader.style.opacity = '0'; }, 150);
}
new MutationObserver(() => {
  appRoot.classList.remove('page-anim');
  void appRoot.offsetWidth;
  appRoot.classList.add('page-anim');
}).observe(appRoot, { childList: true });

function parseHash(){
  const h = (location.hash || '#/').replace(/^#\/?/, '');
  const [name, param] = h.split('/');
  return { name: name || 'home', param };
}
window.addEventListener('hashchange', router);
window.addEventListener('popstate', (e) => {
  // supports the phone's physical/gesture back button: if a modal is open
  // and back is pressed, close the modal instead of exiting the page.
  if (!(e.state && e.state.modal) && authOverlay.classList.contains('open')) {
    authOverlay.classList.remove('open');
  }
});
/* ---- Content protection: watermark + global copy/right-click blocking.
   None of this can stop a determined screen recording, but it removes the
   easy paths (select+copy, right-click save, drag out an image) and — via
   the watermark — makes a leaked screenshot traceable to whoever took it. ---- */
let _watermarkBuilt = false;
function buildWatermarkIfNeeded(){
  if (_watermarkBuilt || !session.user) return;
  const label = `${session.user.name || session.user.email || ''} — ${session.user.email || ''}`;
  const row = `<div class="wm-row">${Array.from({length:8}).map(()=>escapeHtml(label)).join('&nbsp;&nbsp;&nbsp;&nbsp;')}</div>`;
  const rows = Array.from({length:10}).map((_,i)=>`<div class="wm-row" style="top:${i*11}%">${Array.from({length:8}).map(()=>escapeHtml(label)).join('&nbsp;&nbsp;&nbsp;&nbsp;')}</div>`).join('');
  document.getElementById('watermarkOverlay').innerHTML = rows;
  _watermarkBuilt = true;
}
function toggleWatermark(shouldShow){
  const el = document.getElementById('watermarkOverlay');
  if (!el) return;
  if (shouldShow && session.user) { buildWatermarkIfNeeded(); el.classList.add('show'); }
  else el.classList.remove('show');
}
document.addEventListener('contextmenu', (e) => {
  // still allow right-click inside a text input/textarea (paste, etc.)
  const tag = (e.target.tagName||'').toLowerCase();
  if (tag !== 'input' && tag !== 'textarea') e.preventDefault();
});
document.addEventListener('copy', (e) => { if (session.user) e.preventDefault(); });
document.addEventListener('cut', (e) => { if (session.user) e.preventDefault(); });
document.addEventListener('dragstart', (e) => {
  if ((e.target.tagName||'').toLowerCase() === 'img') e.preventDefault();
});

/* =====================================================================
   Abuse protection: (a) 3 failed sign-in/sign-up attempts lock the site for
   8 hours, (b) at most 2 password-reset / verification emails per 8 hours,
   (c) a banned account sees a locked screen with only the logo, the team
   email and the ban reason.
   NOTE: (a) and (b) are enforced in this browser (localStorage) — they stop
   normal misuse, but clearing site data resets them. Hard enforcement needs
   server-side rules. Firebase Auth also applies its own too-many-requests
   throttling on top of this.
   ===================================================================== */
const TEAM_EMAIL = 'contact@sarmad.qd.je';
const RateGuard = {
  WINDOW_MS: 8*60*60*1000, MAX_FAILS: 3, MAX_EMAILS: 2,
  _get(k){ try { return JSON.parse(localStorage.getItem(k)||'null'); } catch(e){ return null; } },
  _set(k,v){ try { localStorage.setItem(k, JSON.stringify(v)); } catch(e){} },
  lockedUntil(){ const t = this._get('sarmad_lock_until'); return (t && t > Date.now()) ? t : 0; },
  registerFail(){
    const c = (this._get('sarmad_fail_count')||0) + 1;
    if (c >= this.MAX_FAILS) { this._set('sarmad_lock_until', Date.now()+this.WINDOW_MS); this._set('sarmad_fail_count', 0); }
    else this._set('sarmad_fail_count', c);
    return this.lockedUntil();
  },
  clearFails(){ this._set('sarmad_fail_count', 0); },
  _recentEmails(){ return (this._get('sarmad_email_sends')||[]).filter(t => Date.now()-t < this.WINDOW_MS); },
  canSendEmail(){ return this._recentEmails().length < this.MAX_EMAILS; },
  nextEmailAt(){ const r = this._recentEmails().sort((a,b)=>a-b); return r.length ? r[0]+this.WINDOW_MS : 0; },
  recordEmail(){ const r = this._recentEmails(); r.push(Date.now()); this._set('sarmad_email_sends', r); },
};
function fmtRemaining(ms){
  const h = Math.floor(ms/3600000), m = Math.floor((ms%3600000)/60000);
  return h ? `${h} ساعة و${m} دقيقة` : `${m} دقيقة`;
}
function emailLimitMessage(){
  return `وصلت للحد الأقصى (2 طلب كل 8 ساعات) — جرّب بعد ${fmtRemaining(Math.max(0, RateGuard.nextEmailAt()-Date.now()))}`;
}
function showLockdownScreen(title, lines){
  let el = document.getElementById('lockdownOverlay');
  if (!el) { el = document.createElement('div'); el.id = 'lockdownOverlay'; document.body.appendChild(el); }
  el.style.cssText = 'position:fixed; inset:0; z-index:100000; background:var(--canvas,#fff); display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; padding:24px; gap:18px;';
  el.innerHTML = `<img src="${BRAND_WORDMARK}" alt="sarmad" style="height:34px; width:auto;" draggable="false">
    <h2 style="font-family:'AppTitles';">${title}</h2>
    ${lines.map(l=>`<p style="max-width:420px; color:var(--ink-soft); line-height:1.8;">${l}</p>`).join('')}
    <a href="mailto:${TEAM_EMAIL}" style="font-family:'AppSub';">${TEAM_EMAIL}</a>`;
}
function showSiteLock(){
  const until = RateGuard.lockedUntil();
  showLockdownScreen('تم تعطيل الموقع مؤقتًا', [
    'بسبب محاولات دخول أو تسجيل فاشلة متكررة، تم إيقاف الموقع لمدة 8 ساعات.',
    `المتبقي: ${fmtRemaining(until-Date.now())}`,
  ]);
}
function showBanScreen(reason){
  showLockdownScreen('تم حظر حسابك', [ `سبب الحظر: ${escapeHtml(reason||'غير محدد')}`, 'للاستفسار تواصل مع فريق سرمد:' ]);
}
// after a failed attempt: count it, and lock the whole site if that was the 3rd
function noteAuthFailure(){ if (RateGuard.registerFail()) showSiteLock(); }

