    if (st.accreditation_pdf_en) parts.push(`<a href="${escapeHtml(st.accreditation_pdf_en)}" target="_blank" rel="noopener" download>Sarmad General Accreditation (English)</a>`);
    host.innerHTML = parts.join(' ');
