async function router(){
  const { name, param } = parseHash();
  window.scrollTo({ top:0, left:0, behavior:'instant' });
  startTopLoader();
  // Leaving an in-progress quiz without submitting used to leave its
  // countdown `setInterval` running forever in the background (it silently
  // no-ops once quizState is cleared, but never actually gets cleared) —
  // each abandoned quiz added one more timer ticking every second for the
  // rest of the session, which both slowed the app down over time and could
  // cause a stray auto-submit to fire later, making a finished exam look
  // like it "replays". Clearing it here on every navigation fixes both.
  if (quizState) {
    clearInterval(quizState._timer);
    quizState = null;
  }
  // Account required site-wide: browsing without an account is no longer
  // allowed. The one exception is the public certificate-verification page
  // — that's meant to be checkable by anyone (an employer, for instance)
  // who isn't a registered student at all.
  if (!session.user && name !== 'certificate') {
    renderLoginRequired();
    doneTopLoader();
    return;
  }
  // Watermark shows only on the content pages worth protecting (lectures,
  // tasks, quizzes) — not on the homepage or dashboard, where it would just
  // be visual noise with nothing to trace back.
  if (RateGuard.lockedUntil()) { showSiteLock(); return; }
  if (session.user && session.user.banned) { showBanScreen(session.user.ban_reason); return; }
  const _ld = document.getElementById('lockdownOverlay'); if (_ld) _ld.remove();
  toggleWatermark(['lecture','task','quiz'].includes(name));
  try {
    if (name==='home') await renderHome();
    else if (name==='tracks') await renderAllTracks();
    else if (name==='courses') await renderAllCourses();
    else if (name==='track') await renderTrack(param);
    else if (name==='course') await renderCourse(param);
    else if (name==='lecture') await renderLecture(param);
    else if (name==='task') await renderTask(param);
    else if (name==='quiz') await renderQuiz(param);
    else if (name==='payment') await renderPayment(param);
    else if (name==='track-payment') await renderTrackPayment(param);
    else if (name==='certificate') await renderCertificate(param);
    else if (name==='dashboard') await renderDashboard();
    else if (name==='leaderboard') await renderLeaderboard();
    else if (name==='forum') await renderForum();
    else if (name==='forum-post') await renderForumPost(param);
    else appRoot.innerHTML = render404();
  } catch (e) {
    appRoot.innerHTML = emptyState('تعذّر تحميل الصفحة', dbFriendlyError(e));
  } finally {
    doneTopLoader();
  }
}
