function skeletonCards(n){ return Array.from({length:n}).map(()=>`<div class="card"><div class="thumb skel"></div><div class="body"><div class="kicker">&nbsp;</div><h3>&nbsp;</h3></div></div>`).join(''); }
async function loadTracksGrid(){
  const grid = document.getElementById('tracksGrid'); if(!grid) return;
  try {
    const [tracks, bookmarkedIds] = await Promise.all([DB.listAll('Tracks'), getBookmarkedIds('track')]);
    const sorted = [...tracks].sort((a,b)=>{
      const fa=a.status==='finished'?1:0, fb=b.status==='finished'?1:0;
      return fa!==fb ? fa-fb : (a.name_ar||'').localeCompare(b.name_ar||'','ar');
    });
    grid.innerHTML = sorted.length ? sorted.map(t=>`
      <div class="card" onclick="navigate('track/${t.id}')">
        <div class="thumb">${t.icon_url?`<img src="${escapeHtml(t.icon_url)}" alt="" loading="lazy" decoding="async">`:icon('book')}
          ${t.status==='finished'?`<span class="status-pill finished">منتهي</span>`:''}
          ${bookmarkBtn('track', t.id, bookmarkedIds.has(String(t.id)))}</div>
        <div class="body"><div class="kicker">مسار</div><h3>${escapeHtml(t.name_ar||'مسار')}</h3></div>
      </div>`).join('') : emptyState('لا توجد مسارات بعد','سيتم إضافتها قريبًا');
  } catch(e){ grid.innerHTML = emptyState('تعذّر تحميل المسارات', dbFriendlyError(e)); }
}
async function loadCoursesGrid(){
  const grid = document.getElementById('coursesGrid'); if(!grid) return;
  try {
    const [courses, bookmarkedIds] = await Promise.all([DB.listAll('Courses'), getBookmarkedIds('course')]);
    const sorted = [...courses].sort((a,b)=>{
      const fa=a.status==='finished'?1:0, fb=b.status==='finished'?1:0;
      return fa!==fb ? fa-fb : (a.title_ar||'').localeCompare(b.title_ar||'','ar');
    }).slice(0,6);
    grid.innerHTML = sorted.length ? sorted.map(c=>`
      <div class="card" onclick="navigate('course/${c.id}')">
        <div class="thumb">${c.cover_image_url?`<img src="${escapeHtml(c.cover_image_url)}" alt="" loading="lazy" decoding="async">`:icon('book')}
          ${c.status==='finished'?`<span class="status-pill finished">منتهية</span>`:''}
          ${bookmarkBtn('course', c.id, bookmarkedIds.has(String(c.id)))}</div>
        <div class="body"><div class="kicker">${escapeHtml(c.instructor_name||'')}</div><h3>${escapeHtml(c.title_ar||'دورة')}</h3></div>
      </div>`).join('') : emptyState('لا توجد دورات بعد','سيتم إضافتها قريبًا');
  } catch(e){ grid.innerHTML = emptyState('تعذّر تحميل الدورات', dbFriendlyError(e)); }
}

/* ---- Feature 3: Bookmarks / favorites ---- */
let _bookmarksCache = null; // avoids two separate Firestore reads when both grids load together
async function getAllBookmarks(){
  if (!session.user) return [];
  if (_bookmarksCache) return _bookmarksCache;
  try {
    _bookmarksCache = await DB.listAll('Bookmarks', 'user_id', session.user.uid);
    return _bookmarksCache;
  } catch(e){ return []; }
}
async function getBookmarkedIds(itemType){
  const rows = await getAllBookmarks();
  return new Set(rows.filter(r=>r.item_type===itemType).map(r=>String(r.item_id)));
}
function bookmarkBtn(itemType, itemId, active){
  return `<button class="bookmark-btn ${active?'active':''}" onclick="event.stopPropagation(); toggleBookmark('${itemType}','${itemId}', this)">${icon(active?'heartFill':'heart')}</button>`;
}
async function toggleBookmark(itemType, itemId, btnEl){
  if (!session.user){ openAuth('login'); return; }
  const docId = `${session.user.uid}_${itemType}_${itemId}`;
  const isActive = btnEl.classList.contains('active');
  try {
    if (isActive) {
      await DB.remove('Bookmarks', docId);
      btnEl.classList.remove('active'); btnEl.innerHTML = icon('heart');
      if (currentTab==='bookmarks') loadDashPanel('bookmarks');
    } else {
      await DB.create('Bookmarks', { user_id:session.user.uid, item_type:itemType, item_id:itemId, created_at:new Date().toISOString() }, docId);
      btnEl.classList.add('active'); btnEl.innerHTML = icon('heartFill');
    }
    _bookmarksCache = null;
  } catch(e){ toast(dbFriendlyError(e)); }
}

