/* ---- Dedicated courses page: search box + track/price/status filters,
   instead of the home page's fixed first-6 preview. ---- */
async function renderAllCourses(){
  appRoot.innerHTML = `<div class="wrap page-head">${backButton()}<h1>${icon('book')} كل الدورات</h1></div>
  <div class="wrap section">
    <div class="filter-bar">
      <input type="text" id="coursesSearchInput" placeholder="ابحث باسم الدورة أو المحاضر...">
      <div id="coursesTrackFilter"></div>
      <div id="coursesPriceFilter"></div>
      <div id="coursesStatusFilter"></div>
    </div>
    <div class="grid" id="allCoursesGrid">${skeletonCards(6)}</div>
  </div>`;
  try {
    const [courses, tracks, bookmarkedIds] = await Promise.all([DB.listAll('Courses'), DB.listAll('Tracks'), getBookmarkedIds('course')]);
    const trackOptions = [{value:'',label:'كل المسارات'}, ...tracks.map(t=>({value:t.id, label:t.name_ar||''}))];
    document.getElementById('coursesTrackFilter').innerHTML = cselectHtml('coursesTrackSel', trackOptions, '');
    document.getElementById('coursesPriceFilter').innerHTML = cselectHtml('coursesPriceSel', [{value:'',label:'كل الأسعار'},{value:'free',label:'مجانية'},{value:'paid',label:'مدفوعة'}], '');
    document.getElementById('coursesStatusFilter').innerHTML = cselectHtml('coursesStatusSel', [{value:'',label:'كل الحالات'},{value:'ongoing',label:'شغّالة'},{value:'finished',label:'منتهية'}], '');
    initCustomSelects();

    function draw(){
      const q = (document.getElementById('coursesSearchInput').value||'').trim().toLowerCase();
      const trackSel = cselectValue('coursesTrackSel');
      const priceSel = cselectValue('coursesPriceSel');
      const statusSel = cselectValue('coursesStatusSel');
      let list = courses.filter(c => {
        if (q) {
          const hay = `${c.title_ar||''} ${c.title_en||''} ${c.instructor_name||''}`.toLowerCase();
          if (!hay.includes(q)) return false;
        }
        if (trackSel && String(c.track_id)!==String(trackSel)) return false;
        if (priceSel==='free' && Number(c.price)>0) return false;
        if (priceSel==='paid' && !(Number(c.price)>0)) return false;
        if (statusSel && (c.status||'ongoing')!==statusSel) return false;
        return true;
      });
      // ongoing courses first, then finished ones, alphabetical within each group
      list = list.sort((a,b) => {
        const fa = a.status==='finished'?1:0, fb = b.status==='finished'?1:0;
        if (fa!==fb) return fa-fb;
        return (a.title_ar||'').localeCompare(b.title_ar||'', 'ar');
      });
      const grid = document.getElementById('allCoursesGrid');
      grid.innerHTML = list.length ? list.map(c=>`
        <div class="card" onclick="navigate('course/${c.id}')">
          <div class="thumb">${c.cover_image_url?`<img src="${escapeHtml(c.cover_image_url)}" alt="" loading="lazy" decoding="async">`:icon('book')}
            ${c.status==='finished'?`<span class="status-pill finished">منتهية</span>`:''}
            ${bookmarkBtn('course', c.id, bookmarkedIds.has(String(c.id)))}</div>
          <div class="body"><div class="kicker">${escapeHtml(c.instructor_name||'')}</div><h3>${escapeHtml(c.title_ar||'دورة')}</h3>
            <div class="meta">${Number(c.price)>0?`${c.price} ج.م`:'مجانية'}</div>
          </div>
        </div>`).join('') : emptyState('لا توجد نتائج','جرّب كلمة بحث أو فلتر مختلف');
    }
    document.getElementById('coursesSearchInput').addEventListener('input', draw);
    document.getElementById('coursesTrackSel').addEventListener('cselect-change', draw);
    document.getElementById('coursesPriceSel').addEventListener('cselect-change', draw);
    document.getElementById('coursesStatusSel').addEventListener('cselect-change', draw);
    draw();
  } catch(e){ document.getElementById('allCoursesGrid').innerHTML = emptyState('تعذّر تحميل الدورات', dbFriendlyError(e)); }
}

