/* ---- Track-completion certificate request — same idea as a single
   course's "أكملت الدورة! اطلب شهادتك" box, but only unlocks once every
   course inside the track is individually 100% complete. Without this the
   track never surfaced a way to ask for its certificate at all. ---- */
async function loadTrackCertRequestBox(trackId, courses){
  try {
    const [allTasks, allLectures, progress, certs] = await Promise.all([
      DB.listAll('Tasks'), DB.listAll('Lectures'), getUserProgress(),
      DB.listAll('Certificates', 'user_id', session.user.uid),
    ]);
    const doneIds = new Set(progress.filter(p=>String(p.completed).toUpperCase()==='TRUE').map(p=>String(p.task_id)));
    const allComplete = courses.every(c => {
      const courseLectureIds = allLectures.filter(l=>String(l.course_id)===String(c.id)).map(l=>l.id);
      const courseTasks = allTasks.filter(t=>courseLectureIds.some(lid=>String(lid)===String(t.lecture_id)));
      return courseTasks.length && courseTasks.every(t=>doneIds.has(String(t.id)));
    });
    if (!allComplete) return;
    const trackLectures = allLectures.filter(l=>courses.some(c=>String(c.id)===String(l.course_id)));
    let eligible = checkDeadlineEligibility(trackLectures, allTasks, progress);
    let reason = eligible ? null : 'deadline';
    if (eligible) {
      const trackAssignmentTasks = allTasks.filter(t => t.type==='assignment' && trackLectures.some(l=>String(l.id)===String(t.lecture_id)));
      if (trackAssignmentTasks.length) {
        const mySubs = await DB.listAll('Submissions', 'user_id', session.user.uid);
        const allApproved = trackAssignmentTasks.every(t => mySubs.some(s=>String(s.task_id)===String(t.id) && s.status==='approved'));
        if (!allApproved) { eligible = false; reason = 'review'; }
      }
    }
    if (!eligible) {
      const host = document.getElementById('trackCertBox') || (() => {
        const el = document.createElement('div'); el.id='trackCertBox'; el.className='wrap section'; el.style.paddingTop='0';
        document.getElementById('trackCourses').closest('.wrap.section').insertAdjacentElement('afterend', el);
        return el;
      })();
      const msg = reason==='review'
        ? { h:'بانتظار مراجعة الأدمن', s:'لسه في تسليم محتاج موافقة الأدمن قبل ما تقدر تطلب شهادة المسار' }
        : { h:'فقدت أهلية شهادة هذا المسار', s:'تجاوزت الموعد النهائي لتسليم إحدى المحاضرات' };
      host.innerHTML = `<div class="list-item" style="cursor:default; border-color:var(--danger);"><div class="num">${icon('lock')}</div><div class="info"><h4>${msg.h}</h4><span>${msg.s}</span></div></div>`;
      return;
    }
    const host = document.getElementById('trackCertBox') || (() => {
      const el = document.createElement('div');
      el.id = 'trackCertBox';
      el.className = 'wrap section';
      el.style.paddingTop = '0';
      document.getElementById('trackCourses').closest('.wrap.section').insertAdjacentElement('afterend', el);
      return el;
    })();
    const existing = certs.find(c=>c.cert_type==='track' && String(c.track_id)===String(trackId));
    if (existing) {
      host.innerHTML = `<div class="list-item" style="cursor:default; border-color:var(--gold);"><div class="num">${icon('badge')}</div><div class="info"><h4>${existing.status==='issued'?'شهادة المسار جاهزة':'طلب شهادة المسار قيد المراجعة'}</h4><span>${existing.status==='issued'?'اضغط لعرضها':'سيتم إشعارك فور اعتمادها'}</span></div>${existing.status==='issued'?`<button class="btn btn-primary btn-sm" onclick="navigate('certificate/${existing.verify_code}')">عرض</button>`:''}</div>`;
      return;
    }
    host.innerHTML = `<div class="list-item" style="cursor:default; border-color:var(--gold);"><div class="num">${icon('badge')}</div><div class="info"><h4>أكملت المسار بالكامل!</h4><span>اطلب شهادة إتمام المسار الآن</span></div><button class="btn btn-gold btn-sm" id="requestTrackCertBtn">${icon('badge')} طلب شهادة</button></div>`;
    document.getElementById('requestTrackCertBtn').addEventListener('click', () => ensureCertFeePaid(() => openTrackCertRequestModal(trackId)));
  } catch(e){ console.error(e); }
}
/* =====================================================================
   New feature: paid certificate/track-certificate requests — 150 ج.م via a
   specific Vodafone Cash link, with photo-proof upload, reviewed by the
   admin in the same Payments tab as course payments (fee_type:'cert_fee').
   Additive only: nothing about the existing free excellence-accreditation
   flow (>=97%) is touched by this — that one still issues automatically.
   ===================================================================== */
async function ensureCertFeePaid(onPaid){
  if (!session.user) { openAuth('login'); return; }
  try {
    const payments = await DB.listAll('Payments', 'user_id', session.user.uid);
    const paid = payments.some(p => p.fee_type==='cert_fee' && p.status==='approved');
    if (paid) { onPaid(); return; }
    const pending = payments.some(p => p.fee_type==='cert_fee' && p.status==='pending');
    openCertFeeModal(pending, onPaid);
  } catch(e){ toast(dbFriendlyError(e)); }
}
function openCertFeeModal(alreadyPending, onPaid){
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay open';
  if (alreadyPending) {
    overlay.innerHTML = `<div class="modal">
      <div class="modal-head"><h2>${icon('badge')} رسوم الشهادة</h2><button class="modal-close" id="certFeeClose">✕</button></div>
      <p style="line-height:1.9;">طلب دفع الرسوم عندك قيد المراجعة من الإدارة. هتقدر تطلب شهادتك أول ما يتم اعتماد الدفع.</p>
    </div>`;
    document.body.appendChild(overlay);
    overlay.addEventListener('click', e => { if (e.target===overlay) overlay.remove(); });
    overlay.querySelector('#certFeeClose').addEventListener('click', () => overlay.remove());
    return;
  }
  overlay.innerHTML = `<div class="modal">
    <div class="modal-head"><h2>${icon('badge')} رسوم إصدار الشهادة</h2><button class="modal-close" id="certFeeClose">✕</button></div>
    <p style="line-height:1.9;">إصدار الشهادة برسوم قدرها <strong>${CONFIG.CERT_FEE_AMOUNT} جنيه</strong>، تُدفع عن طريق فودافون كاش من الرابط التالي فقط:</p>
    <div class="share-row" style="margin-bottom:16px;"><a class="btn btn-primary btn-sm" href="${CONFIG.CERT_FEE_VODAFONE_LINK}" target="_blank" rel="noopener">${icon('doc')} فتح رابط الدفع (فودافون كاش)</a></div>
    <div class="field"><label>ارفع صورة إثبات الدفع *</label><input type="file" accept="image/*" id="certFeeProof"></div>
    <button class="btn btn-primary btn-block" id="certFeeSubmitBtn">إرسال إثبات الدفع</button>
    <p style="font-size:12px; color:var(--ink-soft); margin-top:10px;">هتقدر تطلب شهادتك بعد ما الإدارة تراجع وتعتمد الدفع.</p>
  </div>`;
  document.body.appendChild(overlay);
  overlay.addEventListener('click', e => { if (e.target===overlay) overlay.remove(); });
  overlay.querySelector('#certFeeClose').addEventListener('click', () => overlay.remove());
  overlay.querySelector('#certFeeSubmitBtn').addEventListener('click', async () => {
    const file = overlay.querySelector('#certFeeProof').files[0];
    if (!file) { toast('ارفع صورة إثبات الدفع أولًا'); return; }
    const btn = overlay.querySelector('#certFeeSubmitBtn');
    btn.disabled = true; btn.textContent = '...جارٍ الإرسال';
    try {
      const proofUrl = await ImgBB.upload(file);
      await DB.create('Payments', {
        user_id: session.user.uid, user_email: session.user.email, method:'vodafone', fee_type:'cert_fee',
        amount: CONFIG.CERT_FEE_AMOUNT, proof_url: proofUrl, status:'pending', created_at: new Date().toISOString(),
      });
      toast('تم إرسال إثبات الدفع، بانتظار اعتماد الإدارة');
      overlay.remove();
    } catch(e){ toast(dbFriendlyError(e)); btn.disabled=false; btn.textContent='إرسال إثبات الدفع'; }
  });
}

function openTrackCertRequestModal(trackId){
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay open';
  overlay.innerHTML = `<div class="modal">
    <div class="modal-head"><h2>${icon('badge')} طلب شهادة المسار</h2><button class="modal-close" id="trackCertModalClose">✕</button></div>
    <div class="field"><label>لغة الشهادة</label>
      ${cselectHtml('trackCertReqLang', [{value:'ar',label:'عربي'},{value:'en',label:'إنجليزي'},{value:'both',label:'الاثنين معًا'}], 'ar')}
    </div>
    <div class="field" id="trackCertNameArField"><label>الاسم بالعربي (للشهادة العربية)</label><input type="text" id="trackCertNameAr" value="${escapeHtml(session.user.name||'')}" placeholder="اكتب اسمك بالعربي"></div>
    <div class="field" id="trackCertNameEnField"><label>Name in English (for the English certificate)</label><input type="text" id="trackCertNameEn" value="${escapeHtml(session.user.nameEn||'')}" placeholder="Your name in English"></div>
    <p style="font-size:12.5px; color:var(--ink-soft); margin-bottom:16px;">سيتم مراجعة طلبك من الإدارة، وسيصلك إشعار فور اعتماد الشهادة.</p>
    <button class="btn btn-primary btn-block" id="trackCertSubmitBtn">إرسال الطلب</button>
  </div>`;
  document.body.appendChild(overlay);
  initCustomSelects(overlay);
  const close = () => overlay.remove();
  overlay.addEventListener('click', e => { if (e.target===overlay) close(); });
  overlay.querySelector('#trackCertModalClose').addEventListener('click', close);
  function syncNameFields(){
    const lang = cselectValue('trackCertReqLang');
    overlay.querySelector('#trackCertNameArField').style.display = lang==='en' ? 'none' : 'block';
    overlay.querySelector('#trackCertNameEnField').style.display = lang==='ar' ? 'none' : 'block';
  }
  overlay.querySelector('#trackCertReqLang').addEventListener('cselect-change', syncNameFields);
  syncNameFields();
  overlay.querySelector('#trackCertSubmitBtn').addEventListener('click', async () => {
    const lang = cselectValue('trackCertReqLang');
    const nameAr = overlay.querySelector('#trackCertNameAr').value.trim();
    const nameEn = overlay.querySelector('#trackCertNameEn').value.trim();
    if (lang!=='en' && !nameAr){ toast('اكتب اسمك بالعربي'); return; }
    if (lang!=='ar' && !nameEn){ toast('Enter your name in English'); return; }
    const btn = overlay.querySelector('#trackCertSubmitBtn');
    btn.disabled = true; btn.textContent = '...جارٍ الإرسال';
    try {
      await DB.create('Certificates', {
        user_id: session.user.uid, user_email: session.user.email, track_id: trackId, cert_type:'track',
        full_name_ar: nameAr, full_name_en: nameEn, language: lang,
        status:'pending', verify_code:'', issued_at:'', created_at:new Date().toISOString(),
      });
      toast('تم إرسال طلب شهادة المسار، بانتظار اعتماد الإدارة');
      close(); loadTrackCertRequestBox(trackId, window._lastTrackCourses||[]);
    } catch(e){ toast(dbFriendlyError(e)); btn.disabled=false; btn.textContent='إرسال الطلب'; }
  });
}

