async function renderCourse(id){
  appRoot.innerHTML = `<div class="wrap page-head">${backButton()}${crumb([{label:'الرئيسية',href:'#/'},{label:'الدورة'}])}
    <h1 id="courseTitle">...</h1><p id="courseDesc"></p>${shareRow('course/'+id)}
    <div id="coursePriceBadge" style="margin-top:14px;"></div>
    <div id="ratingSummary" style="margin-top:10px;"></div>
    <div style="margin-top:18px;"><div class="progress-bar" id="courseProgressBar"><div style="width:0%"></div></div></div>
    <div id="certRequestBox"></div>
    <div id="accredBox"></div>
  </div>
  <div class="wrap section"><div id="waitlistBox"></div><div class="list" id="lectureList"></div></div>
  <div class="wrap section" id="courseFaqSection" style="display:none;">
    <div class="section-head"><h2>${icon('quiz')} أسئلة شائعة</h2></div>
    <div id="courseFaqList"></div>
  </div>
  <div class="wrap section" style="padding-top:0;">
    <div class="section-head"><h2>${icon('star')} تقييمات الطلاب</h2></div>
    <div id="reviewForm"></div>
    <div class="list" id="reviewsList" style="margin-top:16px;"></div>
  </div>`;
  const [courses, lectures, progress, tracks] = await Promise.all([DB.listAll('Courses'), DB.listAll('Lectures'), getUserProgress(), DB.listAll('Tracks')]);
  const course = courses.find(c=>String(c.id)===String(id));
  document.getElementById('courseTitle').textContent = course ? course.title_ar : 'دورة غير موجودة';
  document.getElementById('courseDesc').textContent = course ? course.description_ar||'' : '';
  if (course && course.notice) checkCourseNotice(course, id);
  const price = Number(course?.price) || 0;
  // a course flagged non-standalone (part of a paid track) can't be bought on
  // its own — point the student at the track subscription instead
  const isStandalone = course?.standalone !== false;
  const courseTrack = course ? tracks.find(t=>String(t.id)===String(course.track_id)) : null;
  if (price > 0 && !isStandalone) {
    document.getElementById('coursePriceBadge').innerHTML = `<span class="price-badge paid">${icon('lock')} جزء من مسار مدفوع</span>
      ${courseTrack ? `<button class="btn btn-primary btn-sm" onclick="navigate('track/${courseTrack.id}')">${icon('wallet')} الاشتراك في مسار «${escapeHtml(courseTrack.name_ar||'')}»</button>` : ''}`;
  } else {
    document.getElementById('coursePriceBadge').innerHTML = price > 0
      ? `<span class="price-badge paid">${price} ج.م</span> <button class="btn btn-primary btn-sm" onclick="navigate('payment/${id}')">${icon('wallet')} الاشتراك في الدورة</button>`
      : `<span class="price-badge free">${icon('check')} مجانية</span>`;
  }
  const courseLectures = lectures.filter(l=>String(l.course_id)===String(id)).sort((a,b)=>(a.order||0)-(b.order||0));

  const tasks = await DB.listAll('Tasks');
  const allCourseTasks = tasks.filter(t=>courseLectures.some(l=>String(l.id)===String(t.lecture_id)));
  const doneIds = new Set(progress.filter(p=>String(p.completed).toUpperCase()==='TRUE').map(p=>String(p.task_id)));
  const pct = allCourseTasks.length ? Math.round(100*allCourseTasks.filter(t=>doneIds.has(String(t.id))).length/allCourseTasks.length) : 0;
  const courseProgressBarEl = document.getElementById('courseProgressBar');
  courseProgressBarEl.innerHTML = `<div style="width:${pct}%"></div>`;
  courseProgressBarEl.classList.toggle('complete', pct>=100 && allCourseTasks.length>0);
  if (pct >= 100 && allCourseTasks.length) {
    let eligible = checkDeadlineEligibility(courseLectures, tasks, progress);
    let reason = eligible ? null : 'deadline';
    if (eligible) {
      const assignmentTasks = allCourseTasks.filter(t=>t.type==='assignment');
      if (assignmentTasks.length) {
        const mySubs = await DB.listAll('Submissions', 'user_id', session.user.uid);
        const allApproved = assignmentTasks.every(t => mySubs.some(s=>String(s.task_id)===String(t.id) && s.status==='approved'));
        if (!allApproved) { eligible = false; reason = 'review'; }
      }
    }
    loadCertRequestBox(id, course, eligible, reason);
    loadAccreditationBox(id, allCourseTasks.filter(t=>t.type==='quiz'));
  }

  if (courseLectures.length){
    document.getElementById('lectureList').innerHTML = courseLectures.map((l,i)=>{
      const lTasks = tasks.filter(t=>String(t.lecture_id)===String(l.id));
      const lDone = lTasks.length && lTasks.every(t=>doneIds.has(String(t.id)));
      const locked = i>0 && !(() => {
        const prevTasks = tasks.filter(t=>String(t.lecture_id)===String(courseLectures[i-1].id));
        return prevTasks.length && prevTasks.every(t=>doneIds.has(String(t.id)));
      })();
      return `<div class="list-item ${lDone?'done':''} ${locked?'locked':''}" ${locked?'':`onclick="navigate('lecture/${l.id}')"`}>
        <div class="num">${lDone?icon('check'):(i+1)}</div>
        <div class="info"><h4>${escapeHtml(l.title_ar||'محاضرة')}</h4><span>${lTasks.length} مهمة${l.estimated_minutes ? ` · ~${l.estimated_minutes} دقيقة` : ''}</span></div>
        <div class="status-icon">${locked?icon('lock'):icon('chevron')}</div>
      </div>`;
    }).join('');
  } else {
    document.getElementById('lectureList').innerHTML = emptyState('لا توجد محاضرات بعد','ستُضاف قريبًا');
    loadWaitlistBox(id); // feature 6: only relevant while the course has no content yet
  }
  loadCourseReviews(id);
  loadCourseFaq(id);
}
