/* ---- Excellence accreditation (A4, Arabic + English): shown ONLY when the
   course is fully completed AND the student's average of their best score on
   each of the course's quizzes is ACCRED_MIN_SCORE or higher. The first time
   they qualify, an issued record is created so the QR/verify code works. ---- */
const ACCRED_MIN_SCORE = 97;
async function loadAccreditationBox(courseId, quizTasks){
  const box = document.getElementById('accredBox');
  if (!box || !session.user || !quizTasks.length) return;
  try {
    const attempts = await DB.listAll('QuizAttempts', 'user_id', session.user.uid);
    const best = quizTasks.map(t => Math.max(0, ...attempts.filter(a=>String(a.task_id)===String(t.id)).map(a=>Number(a.score)||0)));
    const avg = best.reduce((a,b)=>a+b,0) / best.length;
    if (avg < ACCRED_MIN_SCORE) return;
    const certs = await DB.listAll('Certificates', 'user_id', session.user.uid);
    let rec = certs.find(c=>c.cert_type==='accreditation' && String(c.course_id)===String(courseId));
    if (!rec) {
      let nameEn = session.user.nameEn || '';
      if (!nameEn) {
        nameEn = (prompt('اكتب اسمك بالإنجليزي لنسخة الاعتماد الإنجليزية / Your name in English:') || '').trim() || session.user.name || '';
        if (nameEn && nameEn !== session.user.name) { DB.update('Users', session.user.uid, { full_name_en: nameEn }).catch(()=>{}); session.user.nameEn = nameEn; }
      }
      const code = 'ACC-' + Array.from({length:8}, () => 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[Math.floor(Math.random()*32)]).join('');
      rec = {
        user_id: session.user.uid, user_email: session.user.email, cert_type:'accreditation', course_id: courseId,
        full_name_ar: session.user.name || '', full_name_en: nameEn, language:'both',
        status:'issued', verify_code: code, avg_score: Math.round(avg),
        issued_at: new Date().toISOString(), created_at: new Date().toISOString(),
      };
      await DB.create('Certificates', rec);
    }
    box.innerHTML = `<div class="list-item" style="cursor:default; margin-top:16px; border-color:var(--gold);">
      <div class="num"><img src="${BADGE_COURSE_DONE}" alt="" style="width:34px; height:34px; object-fit:contain;"></div>
      <div class="info"><h4>اعتماد التفوق</h4><span>حققت ${Math.round(avg)}% في اختبارات هذه الدورة</span></div>
      <button class="btn btn-gold btn-sm" onclick="navigate('certificate/${rec.verify_code}')">${icon('doc')} عرض وتحميل الاعتماد</button>
    </div>`;
  } catch(e){ console.error(e); }
}

/* ---- Per-lecture submission deadlines: if a lecture has a due_at and the
   student either finished it after that moment, or still hasn't finished
   it and the deadline has now passed, the course/track permanently loses
   certificate eligibility (even if they go back and finish it later). ---- */
function checkDeadlineEligibility(lecturesInScope, tasks, progress){
  const now = Date.now();
  const doneMap = new Map(progress.filter(p=>String(p.completed).toUpperCase()==='TRUE').map(p=>[String(p.task_id), p.completed_at]));
  for (const l of lecturesInScope){
    if (!l.due_at) continue;
    const due = new Date(l.due_at).getTime();
    const lTasks = tasks.filter(t=>String(t.lecture_id)===String(l.id));
    for (const t of lTasks){
      const completedAt = doneMap.get(String(t.id));
      if (completedAt) { if (new Date(completedAt).getTime() > due) return false; }
      else if (now > due) return false;
    }
  }
  return true;
}

/* ---- Certificate request (student-triggered, admin fulfils) ---- */
async function loadCertRequestBox(courseId, course, eligible, reason){
  const box = document.getElementById('certRequestBox');
  if (!box || !session.user) return;
  if (course && course.has_certificate===false) { box.innerHTML = ''; return; }
  try {
    const existing = (await DB.listAll('Certificates', 'user_id', session.user.uid)).find(c=>c.course_id===courseId);
    if (existing) {
      box.innerHTML = `<div class="list-item" style="cursor:default; margin-top:16px;"><div class="num">${icon('badge')}</div><div class="info"><h4>${existing.status==='issued'?'شهادتك جاهزة':'طلب الشهادة قيد المراجعة'}</h4><span>${existing.status==='issued'?'اضغط لعرضها':'سيتم إشعارك فور اعتمادها'}</span></div>${existing.status==='issued'?`<button class="btn btn-primary btn-sm" onclick="navigate('certificate/${existing.verify_code}')">عرض</button>`:''}</div>`;
      return;
    }
    if (eligible===false) {
      const msg = reason==='review'
        ? { h:'بانتظار مراجعة الأدمن', s:'لسه في تسليم (واجب/مشروع) محتاج يوافق عليه الأدمن قبل ما تقدر تطلب الشهادة' }
        : { h:'فقدت أهلية شهادة هذه الدورة', s:'تجاوزت الموعد النهائي لتسليم إحدى المحاضرات' };
      box.innerHTML = `<div class="list-item" style="cursor:default; margin-top:16px; border-color:var(--danger);"><div class="num">${icon('lock')}</div><div class="info"><h4>${msg.h}</h4><span>${msg.s}</span></div></div>`;
      return;
    }
    box.innerHTML = `<div class="list-item" style="cursor:default; margin-top:16px; border-color:var(--gold);"><div class="num">${icon('badge')}</div><div class="info"><h4>أكملت الدورة!</h4><span>اطلب شهادتك الآن</span></div><button class="btn btn-gold btn-sm" id="requestCertBtn">${icon('badge')} طلب شهادة</button></div>`;
    document.getElementById('requestCertBtn').addEventListener('click', () => ensureCertFeePaid(() => openCertRequestModal(courseId)));
  } catch(e){ console.error(e); }
}
function openCertRequestModal(courseId){
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay open';
  overlay.innerHTML = `<div class="modal">
    <div class="modal-head"><h2>${icon('badge')} طلب شهادة</h2><button class="modal-close" id="certModalClose">✕</button></div>
    <div class="field"><label>لغة الشهادة</label>
      ${cselectHtml('certReqLang', [{value:'ar',label:'عربي'},{value:'en',label:'إنجليزي'},{value:'both',label:'الاثنين معًا'}], 'ar')}
    </div>
    <div class="field" id="certNameArField"><label>الاسم بالعربي (للشهادة العربية)</label><input type="text" id="certReqNameAr" value="${escapeHtml(session.user.name||'')}" placeholder="اكتب اسمك بالعربي"></div>
    <div class="field" id="certNameEnField"><label>Name in English (for the English certificate)</label><input type="text" id="certReqNameEn" value="${escapeHtml(session.user.nameEn||'')}" placeholder="Your name in English"></div>
    <p style="font-size:12.5px; color:var(--ink-soft); margin-bottom:16px;">سيتم مراجعة طلبك من الإدارة، وسيصلك إشعار فور اعتماد الشهادة.</p>
    <button class="btn btn-primary btn-block" id="certReqSubmitBtn">إرسال الطلب</button>
  </div>`;
  document.body.appendChild(overlay);
  initCustomSelects(overlay);
  const close = () => overlay.remove();
  overlay.addEventListener('click', e => { if (e.target===overlay) close(); });
  overlay.querySelector('#certModalClose').addEventListener('click', close);
  function syncNameFields(){
    const lang = cselectValue('certReqLang');
    overlay.querySelector('#certNameArField').style.display = lang==='en' ? 'none' : 'block';
    overlay.querySelector('#certNameEnField').style.display = lang==='ar' ? 'none' : 'block';
  }
  overlay.querySelector('#certReqLang').addEventListener('cselect-change', syncNameFields);
  syncNameFields();
  overlay.querySelector('#certReqSubmitBtn').addEventListener('click', async () => {
    const lang = cselectValue('certReqLang');
    const nameAr = overlay.querySelector('#certReqNameAr').value.trim();
    const nameEn = overlay.querySelector('#certReqNameEn').value.trim();
    if (lang!=='en' && !nameAr){ toast('اكتب اسمك بالعربي'); return; }
    if (lang!=='ar' && !nameEn){ toast('Please enter your name in English'); return; }
    const btn = overlay.querySelector('#certReqSubmitBtn');
    btn.disabled = true; btn.textContent = '...جارٍ الإرسال';
    try {
      // carry the course's skills onto the certificate at request time —
      // otherwise a certificate approved without the admin re-touching this
      // field would ship with no skills listed at all
      const reqCourse = await DB.get('Courses', courseId);
      await DB.create('Certificates', {
        user_id: session.user.uid, user_email: session.user.email, course_id: courseId,
        full_name_ar: nameAr, full_name_en: nameEn, language: lang,
        skills_ar: reqCourse?.skills_ar||'', skills_en: reqCourse?.skills_en||'',
        status:'pending', verify_code:'', issued_at:'', created_at:new Date().toISOString(),
      });
      toast('تم إرسال طلب الشهادة، بانتظار اعتماد الإدارة');
      close(); loadCertRequestBox(courseId);
    } catch(e){ toast(dbFriendlyError(e)); btn.disabled=false; btn.textContent='إرسال الطلب'; }
  });
}

