/* ---- Feature 5: course ratings & reviews ---- */
async function loadCourseReviews(courseId){
  try {
    const reviews = await DB.listAll('Reviews', 'course_id', courseId);
    const avg = reviews.length ? (reviews.reduce((a,r)=>a+(r.rating||0),0)/reviews.length) : 0;
    const summaryEl = document.getElementById('ratingSummary');
    if (summaryEl) summaryEl.innerHTML = reviews.length
      ? `<div style="display:flex; align-items:center; gap:6px; color:var(--gold); font-size:14px;">${'★'.repeat(Math.round(avg))}${'☆'.repeat(5-Math.round(avg))} <span style="color:var(--ink-soft); font-size:12.5px;">(${avg.toFixed(1)} · ${reviews.length} تقييم)</span></div>`
      : '';

    const formHost = document.getElementById('reviewForm');
    if (!session.user){
      formHost.innerHTML = `<button class="btn btn-ghost btn-sm" onclick="openAuth('login')">${icon('star')} سجّل الدخول لتقييم الدورة</button>`;
    } else {
      const mine = reviews.find(r=>r.user_id===session.user.uid);
      const myRating = mine ? mine.rating : 0;
      formHost.innerHTML = `<div class="panel">
        <div class="star-picker" id="starPicker">${[1,2,3,4,5].map(n=>`<span class="icon star-pick ${n<=myRating?'active':''}" data-val="${n}" onclick="setStarRating(${n})">${icon(n<=myRating?'starFill':'star')}</span>`).join('')}</div>
        <div class="field" style="margin-top:10px;"><textarea id="reviewComment" placeholder="اكتب رأيك في الدورة (اختياري)...">${escapeHtml(mine?mine.comment||'':'')}</textarea></div>
        <button class="btn btn-primary btn-sm" id="reviewSubmitBtn">${icon('check')} ${mine?'تحديث تقييمي':'إرسال التقييم'}</button>
      </div>`;
      window._currentStarRating = myRating;
      document.getElementById('reviewSubmitBtn').addEventListener('click', async () => {
        if (!window._currentStarRating){ toast('اختر عدد النجوم أولًا'); return; }
        const commentVal = document.getElementById('reviewComment').value.trim();
        if (containsAbusiveLanguage(commentVal)){ toast('التعليق يحتوي على ألفاظ غير لائقة، عدّله وحاول تاني'); return; }
        const btn = document.getElementById('reviewSubmitBtn');
        btn.disabled = true; btn.textContent = '...جارٍ الحفظ';
        try {
          await DB.create('Reviews', {
            course_id:courseId, user_id:session.user.uid, user_name:session.user.name||'طالب',
            rating:window._currentStarRating, comment:commentVal,
            created_at:new Date().toISOString(),
          }, `${session.user.uid}_${courseId}`);
          toast('تم حفظ تقييمك، شكرًا لك'); loadCourseReviews(courseId);
        } catch(e){ toast(dbFriendlyError(e)); }
        finally { btn.disabled=false; }
      });
    }

    const list = document.getElementById('reviewsList');
    list.innerHTML = reviews.length ? reviews.sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||'')).map(r => `
      <div class="qa-item">
        <div class="qa-q" style="color:var(--gold);">${'★'.repeat(r.rating||0)}${'☆'.repeat(5-(r.rating||0))} <span style="color:var(--ink); font-size:13px; font-weight:600; margin-right:6px;">${escapeHtml(r.user_name||'طالب')}</span></div>
        ${r.comment ? `<div class="qa-meta" style="margin-top:6px; color:var(--ink-soft); font-size:12.5px;">${escapeHtml(r.comment)}</div>` : ''}
      </div>`).join('') : `<div class="hint" style="color:var(--ink-soft); font-size:13px;">لا توجد تقييمات بعد</div>`;
  } catch(e){ console.error(e); }
}
function setStarRating(n){
  window._currentStarRating = n;
  document.querySelectorAll('#starPicker .star-pick').forEach(el => {
    const v = Number(el.dataset.val);
    el.innerHTML = ICONS[v<=n?'starFill':'star'];
    el.classList.toggle('active', v<=n);
  });
}

/* ---------------- LECTURE ---------------- */
async function renderLecture(id){
  appRoot.innerHTML = `<div class="wrap page-head">${backButton()}${crumb([{label:'الرئيسية',href:'#/'},{label:'المحاضرة'}])}
    <h1 id="lectureTitle">...</h1>${shareRow('lecture/'+id)}</div>
  <div class="wrap section"><div class="list" id="taskList"></div></div>
  <div class="wrap section" id="resourcesSection" style="padding-top:0; display:none;">
    <div class="section-head"><h2>${icon('paperclip')} الملفات والمصادر</h2></div>
    <div class="list" id="resourcesList"></div>
  </div>
  <div class="wrap section" style="padding-top:0;">
    <div class="section-head"><h2>${icon('chat')} أسئلة الطلاب</h2></div>
    <div id="qaAskBox"></div>
    <div class="list" id="qaList" style="margin-top:16px;"></div>
  </div>`;
  const [lectures, tasks, progress, courses] = await Promise.all([DB.listAll('Lectures'), DB.listAll('Tasks'), getUserProgress(), DB.listAll('Courses')]);
  const lecture = lectures.find(l=>String(l.id)===String(id));
  const lectureCourse = lecture ? courses.find(c=>String(c.id)===String(lecture.course_id)) : null;
  if (!(await hasApprovedAccessToCourse(lectureCourse))) { renderPaywall(lectureCourse); return; }
  document.getElementById('lectureTitle').textContent = lecture ? lecture.title_ar : 'محاضرة غير موجودة';
  const lTasks = tasks.filter(t=>String(t.lecture_id)===String(id)).sort((a,b)=>(a.order||0)-(b.order||0));
  const doneIds = new Set(progress.filter(p=>String(p.completed).toUpperCase()==='TRUE').map(p=>String(p.task_id)));
  const typeIcon = { video:'play', audio:'headphones', pdf:'doc', quiz:'quiz', text:'text', assignment:'doc' };
  const typeLabel = { video:'فيديو', audio:'صوت', pdf:'ملف PDF', quiz:'اختبار', text:'نص', assignment:'تسليم' };

  document.getElementById('taskList').innerHTML = lTasks.length ? lTasks.map((t,i)=>{
    const tid = t.id;
    const done = doneIds.has(String(tid));
    const locked = i>0 && !doneIds.has(String(lTasks[i-1].id));
    const route = t.type==='quiz' ? `quiz/${tid}` : `task/${tid}`;
    return `<div class="list-item ${done?'done':''} ${locked?'locked':''}" ${locked?'':`onclick="navigate('${route}')"`}>
      <div class="num">${done?icon('check'):(i+1)}</div>
      <div class="info"><h4>${escapeHtml(t.title_ar||'مهمة')}</h4><span>${typeLabel[t.type]||t.type||''}</span></div>
      <div class="status-icon">${locked?icon('lock'):icon(typeIcon[t.type]||'text')}</div>
    </div>`;
  }).join('') : emptyState('لا توجد مهام بعد','ستُضاف قريبًا');

  loadLectureQA(id);
  loadLectureResources(id);
}

