/* =====================================================================
   New feature: POINTS & LEVELS — persisted on Users.points via an atomic
   Firestore increment, so concurrent writes (finishing a task in two tabs)
   never clobber each other the way a plain read-then-write would.
   ===================================================================== */
async function awardPoints(amount){
  if (!session.user || !amount) return;
  try { await fbDb.collection('Users').doc(session.user.uid).update({ points: firebase.firestore.FieldValue.increment(amount) }); }
  catch(e){ console.error(e); }
}
// Four levels, matching the four badge illustrations — thresholds are our
// own call since the level system existed before the badges did: each
// level roughly doubles the climb (0, 150, 400, 900) so early progress
// feels quick and later levels feel earned.
const LEVELS = [
  { min:0,   title:'مبتدئ',  badge: BADGE_LEVEL1 },
  { min:150, title:'مجتهد',  badge: BADGE_LEVEL2 },
  { min:400, title:'متمكّن', badge: BADGE_LEVEL3 },
  { min:900, title:'خبير',   badge: BADGE_LEVEL4 },
];
function levelForPoints(points){
  const p = Number(points)||0;
  let idx = 0;
  for (let i=0; i<LEVELS.length; i++) if (p >= LEVELS[i].min) idx = i;
  const level = idx+1;
  const next = LEVELS[idx+1];
  return { level, title: LEVELS[idx].title, badge: LEVELS[idx].badge, pointsToNext: next ? (next.min - p) : 0 };
}

/* =====================================================================
   New feature: DAILY STUDY STREAK — Users.streak_count / last_active_date,
   updated once per calendar day the student is actually active.
   ===================================================================== */
async function bumpStudyStreak(){
  if (!session.user) return;
  try {
    const today = new Date().toISOString().slice(0,10);
    const userDoc = await DB.get('Users', session.user.uid);
    if (!userDoc || userDoc.last_active_date === today) return; // already counted today
    const yesterday = new Date(Date.now()-86400000).toISOString().slice(0,10);
    const newStreak = userDoc.last_active_date === yesterday ? (Number(userDoc.streak_count)||0)+1 : 1;
    await DB.update('Users', session.user.uid, { streak_count: newStreak, last_active_date: today });
  } catch(e){ console.error(e); }
}

