async function renderDashboard(){
  if (!session.user){ openAuth('login'); appRoot.innerHTML = emptyState('سجّل الدخول أولًا','للوصول إلى لوحتك الشخصية'); return; }
  appRoot.innerHTML = `<div class="wrap page-head"><h1>${icon('user')} لوحتي</h1></div>
  <div class="wrap"><div class="stat-row" id="statRow">${skeletonCards(4)}</div></div>
  <div class="wrap"><div style="display:flex; gap:18px; justify-content:center; margin:18px 0;" id="levelBadgeWall"></div></div>
  <div class="wrap section dash-grid">
    <nav class="dash-nav">
      <button class="active" data-dtab="progress">${icon('book')} تقدّمي</button>
      <button data-dtab="bookmarks">${icon('heartFill')} المفضلة</button>
      <button data-dtab="certs">${icon('badge')} شهاداتي</button>
      <button data-dtab="accred">${icon('doc')} اعتماداتي</button>
      <button data-dtab="review">${icon('pencil')} للمراجعة</button>
      <button data-dtab="referral">${icon('gift')} دعوة الأصدقاء</button>
      <button data-dtab="payments">${icon('wallet')} مدفوعاتي</button>
      <button data-dtab="profile">${icon('user')} الملف الشخصي</button>
      <button data-dtab="pay" onclick="navigate('payment')" style="color:var(--emerald);">${icon('wallet')} الدفع</button>
    </nav>
    <div id="dashPanel">${emptyState('جارٍ التحميل...','')}</div>
  </div>`;
  document.querySelectorAll('[data-dtab]').forEach(b=>{
    if (!b.hasAttribute('onclick')) b.addEventListener('click', ()=>{
      document.querySelectorAll('[data-dtab]').forEach(x=>x.classList.remove('active'));
      b.classList.add('active'); loadDashPanel(b.dataset.dtab);
    });
  });
  loadDashPanel('progress');
  loadDashStats();
}
async function loadDashStats(){
  const row = document.getElementById('statRow');
  if (!row || !session.user) return;
  try {
    const [progress, attempts, certs, userDoc] = await Promise.all([
      getUserProgress(), DB.listAll('QuizAttempts', 'user_id', session.user.uid), DB.listAll('Certificates', 'user_id', session.user.uid), DB.get('Users', session.user.uid),
    ]);
    const completed = progress.filter(p=>String(p.completed).toUpperCase()==='TRUE').length;
    const avgScore = attempts.length ? Math.round(attempts.reduce((a,x)=>a+(x.score||0),0)/attempts.length) : 0;
    const issued = certs.filter(c=>c.status==='issued').length;
    const { level, title, badge } = levelForPoints(userDoc?.points);
    const stats = [
      { icon:'check', label:'مهام مكتملة', value:completed },
      { icon:'quiz', label:'متوسط الاختبارات', value:`${avgScore}%` },
      { icon:'badge', label:'شهادات صادرة', value:issued },
      { badgeImg:badge, label:`نقاطي — المستوى ${level} (${title})`, value:Number(userDoc?.points)||0 },
      { icon:'flame', label:'أيام متتالية', value:Number(userDoc?.streak_count)||0 },
    ];
    row.innerHTML = stats.map(s => `
      <div class="stat-card">
        <div class="stat-icon">${s.badgeImg ? `<img src="${s.badgeImg}" alt="" style="width:32px; height:32px; object-fit:contain;">` : icon(s.icon)}</div>
        <div class="stat-value">${s.value}</div>
        <div class="stat-label">${s.label}</div>
      </div>`).join('');
    // Level badge wall — the four badges, dimmed until reached
    const badgeWallHost = document.getElementById('levelBadgeWall');
    if (badgeWallHost) {
      badgeWallHost.innerHTML = LEVELS.map((l,i) => `
        <div style="text-align:center; opacity:${i<level?1:.3};">
          <img src="${l.badge}" alt="${l.title}" style="width:64px; height:64px; object-fit:contain;">
          <div style="font-size:11px; margin-top:4px;">${l.title}</div>
        </div>`).join('');
    }
  } catch(e){ console.error(e); }
}
// Direct file download of a course accreditation from the dashboard, without
// opening the verify page: builds the A4 card off-screen, then reuses the same
// export path as the certificate page.
async function directDownloadAccreditation(certId, lang, kind){
  const cache = window._accredCache;
  const rec = cache && cache.certs.find(c=>c.id===certId);
  if (!rec) { toast('تعذّر العثور على الاعتماد'); return; }
  const course = cache.courses.find(x=>String(x.id)===String(rec.course_id)) || {};
  const verifyUrl = `${location.origin}${location.pathname}#/certificate/${rec.verify_code}`;
  const isEn = lang === 'en';
  const host = document.createElement('div');
  host.style.cssText = 'position:fixed; left:-10000px; top:0; width:794px;';
  const cardId = 'accDirect_' + Date.now();
  host.innerHTML = accreditationCardHtml(isEn ? rec.full_name_en : rec.full_name_ar, course, cache.settings, (rec.issued_at||'').slice(0,10), verifyUrl, cardId, lang);
  document.body.appendChild(host);
  const fileName = `sarmad-accreditation-${rec.verify_code}-${lang}`;
  try {
    if (kind === 'pdf') await downloadCertificatePdf(cardId, fileName);
    else await downloadCertificateImage(cardId, fileName);
  } finally { host.remove(); }
}
async function loadDashPanel(tab){
  const panel = document.getElementById('dashPanel');
  if (tab==='progress'){
    const [courses, lectures, tasks, progress] = await Promise.all([DB.listAll('Courses'), DB.listAll('Lectures'), DB.listAll('Tasks'), getUserProgress()]);
    const doneIds = new Set(progress.filter(p=>String(p.completed).toUpperCase()==='TRUE').map(p=>String(p.task_id)));
    panel.innerHTML = courses.length ? courses.map(c=>{
      const cLectures = lectures.filter(l=>String(l.course_id)===String(c.id));
      const cTasks = tasks.filter(t=>cLectures.some(l=>String(l.id)===String(t.lecture_id)));
      const pct = cTasks.length ? Math.round(100*cTasks.filter(t=>doneIds.has(String(t.id))).length/cTasks.length) : 0;
      return `<div class="list-item" onclick="navigate('course/${c.id}')">
        <div class="info"><h4>${escapeHtml(c.title_ar||'')}</h4><div class="progress-bar"><div style="width:${pct}%"></div></div></div>
        <div class="status-icon">${pct}%</div></div>`;
    }).join('') : emptyState('لا توجد دورات بعد','تصفّح الدورات وابدأ التعلّم');
  } else if (tab==='bookmarks'){
    const [bookmarks, tracks, courses] = await Promise.all([
      session.user ? DB.listAll('Bookmarks', 'user_id', session.user.uid) : [],
      DB.listAll('Tracks'), DB.listAll('Courses'),
    ]);
    panel.innerHTML = bookmarks.length ? bookmarks.map(b=>{
      const item = b.item_type==='track' ? tracks.find(t=>t.id===b.item_id) : courses.find(c=>c.id===b.item_id);
      if (!item) return '';
      const title = b.item_type==='track' ? item.name_ar : item.title_ar;
      return `<div class="list-item" onclick="navigate('${b.item_type}/${b.item_id}')">
        <div class="num">${icon('heartFill')}</div>
        <div class="info"><h4>${escapeHtml(title||'')}</h4><span>${b.item_type==='track'?'مسار':'دورة'}</span></div>
        <button class="btn btn-ghost btn-sm" onclick="event.stopPropagation(); toggleBookmark('${b.item_type}','${b.item_id}', this)">إزالة</button></div>`;
    }).join('') : emptyState('لا توجد عناصر في المفضلة بعد','اضغط على أيقونة القلب في أي مسار أو دورة لحفظها هنا');
  } else if (tab==='certs'){
    const [certs, courses] = await Promise.all([
      session.user ? DB.listAll('Certificates', 'user_id', session.user.uid) : [],
      DB.listAll('Courses'),
    ]);
    panel.innerHTML = certs.length ? certs.map(c=>`
      <div class="list-item" ${c.status==='issued'?`onclick="navigate('certificate/${c.verify_code}')"`:''}>
        <div class="num">${icon('badge')}</div>
        <div class="info"><h4>${escapeHtml((courses.find(x=>x.id===c.course_id)||{}).title_ar||'دورة')}</h4><span>${c.status==='issued'?'صادرة':c.status==='revoked'?'مُلغاة':'قيد المراجعة'} · ${c.language==='both'?'عربي وإنجليزي':c.language==='en'?'إنجليزي':'عربي'}</span></div>
        <div class="status-icon">${c.status==='issued'?icon('chevron'):c.status==='revoked'?icon('trash'):icon('hourglass')}</div></div>`).join('') : emptyState('لا توجد شهادات بعد','أكمل دورة كاملة لطلب شهادتك من صفحتها');
  } else if (tab==='review'){
    panel.innerHTML = emptyState('جارٍ التحميل...','');
    const flags = (await DB.listAll('TaskFlags', 'user_id', session.user.uid)).filter(f=>f.flagged)
      .sort((a,b)=>(b.updated_at||'').localeCompare(a.updated_at||''));
    panel.innerHTML = flags.length ? flags.map(f => `
      <div class="list-item" onclick="navigate('task/${f.task_id}')">
        <div class="info"><h4>${escapeHtml(f.task_title||'مهمة')}</h4><span>علّمتها للمراجعة · ${escapeHtml((f.updated_at||'').slice(0,10))}</span></div>
        ${icon('chevron')}
      </div>`).join('') : emptyState('لا توجد مهام للمراجعة', 'اضغط "علّم للمراجعة لاحقًا" داخل أي مهمة لتظهر هنا');
  } else if (tab==='accred'){
    panel.innerHTML = emptyState('جارٍ التحميل...','');
    const [certs, courses, settings] = await Promise.all([
      DB.listAll('Certificates', 'user_id', session.user.uid),
      DB.listAll('Courses'),
      DB.get('Settings', 'general').catch(()=>null),
    ]);
    window._accredCache = { certs, courses, settings: settings||{} };
    const mine = certs.filter(c=>c.cert_type==='accreditation' && c.status==='issued')
                      .sort((a,b)=>(b.issued_at||'').localeCompare(a.issued_at||''));
    const st = settings || {};
    const generalHtml = (st.accreditation_pdf_ar || st.accreditation_pdf_en) ? `
      <div class="panel" style="margin-bottom:18px;">
        <h3 style="font-size:15px; margin-bottom:12px;">${icon('doc')} اعتماد سرمد العام</h3>
        <div class="share-row">
          ${st.accreditation_pdf_ar ? `<a class="btn btn-primary btn-sm" href="${escapeHtml(st.accreditation_pdf_ar)}" target="_blank" rel="noopener" download>${icon('doc')} تحميل (عربي) PDF</a>` : ''}
          ${st.accreditation_pdf_en ? `<a class="btn btn-primary btn-sm" href="${escapeHtml(st.accreditation_pdf_en)}" target="_blank" rel="noopener" download>${icon('doc')} Download (English) PDF</a>` : ''}
        </div>
      </div>` : '';
    const courseHtml = mine.length ? mine.map(c => {
      const title = (courses.find(x=>String(x.id)===String(c.course_id))||{}).title_ar || 'دورة';
      return `<div class="panel" style="margin-bottom:12px;">
        <div style="display:flex; align-items:center; gap:12px; margin-bottom:12px;">
          <img src="${BADGE_COURSE_DONE}" alt="" style="width:38px; height:38px; object-fit:contain;">
          <div><h4>${escapeHtml(title)}</h4><span style="font-size:12px; color:var(--ink-soft);">${escapeHtml((c.issued_at||'').slice(0,10))}${c.avg_score?` · ${c.avg_score}%`:''} · ${escapeHtml(c.verify_code||'')}</span></div>
        </div>
        <div class="share-row">
          <button class="btn btn-primary btn-sm" onclick="directDownloadAccreditation('${c.id}','ar','pdf')">${icon('doc')} PDF عربي</button>
          <button class="btn btn-primary btn-sm" onclick="directDownloadAccreditation('${c.id}','en','pdf')">${icon('doc')} PDF English</button>
          <button class="btn btn-ghost btn-sm" onclick="directDownloadAccreditation('${c.id}','ar','img')">${icon('doc')} صورة عربي</button>
          <button class="btn btn-ghost btn-sm" onclick="directDownloadAccreditation('${c.id}','en','img')">${icon('doc')} Image English</button>
          <button class="btn btn-ghost btn-sm" onclick="navigate('certificate/${c.verify_code}')">عرض</button>
        </div>
      </div>`;
    }).join('') : emptyState('لا توجد اعتمادات دورات بعد', `يظهر اعتماد الدورة عند إتمامها بمتوسط اختبارات ${ACCRED_MIN_SCORE}% أو أكثر`);
    panel.innerHTML = generalHtml + courseHtml;
  } else if (tab==='referral'){
    const [refs] = await Promise.all([session.user ? DB.listAll('Referrals', 'referrer_uid', session.user.uid) : []]);
    const code = session.user.referral_code;
    panel.innerHTML = `
      <div class="panel">
        <h3 style="font-size:15px; margin-bottom:12px;">${icon('gift')} كود دعوتك</h3>
        <div class="copy-row"><span>${escapeHtml(code)}</span><button class="btn btn-ghost btn-sm" onclick="copyText('${escapeHtml(code)}')">${icon('copy')} نسخ</button></div>
        <p style="font-size:12.5px; color:var(--ink-soft); margin-top:10px;">شارك الكود ده مع أصدقائك، وخليهم يكتبوه عند إنشاء حسابهم الجديد في سرمد.</p>
      </div>
      <h3 style="font-size:15px; margin:20px 0 10px;">من دعوتهم (${refs.length})</h3>
      <div class="list">${refs.length ? refs.map(r=>`
        <div class="list-item" style="cursor:default;"><div class="num">${icon('user')}</div><div class="info"><h4>${escapeHtml(r.new_user_name||'طالب')}</h4><span>${escapeHtml((r.created_at||'').slice(0,10))}</span></div></div>`).join('') : emptyState('لسه محدش استخدم كودك','شارك الكود لتظهر دعواتك هنا')}</div>`;
  } else if (tab==='payments'){
    const pays = session.user ? await DB.listAll('Payments', 'user_id', session.user.uid) : [];
    panel.innerHTML = pays.length ? pays.map(p=>`
      <div class="list-item"><div class="num">${icon('wallet')}</div>
        <div class="info"><h4>${escapeHtml(p.method||'')}</h4><span>${escapeHtml((p.created_at||'').slice(0,10))}</span></div>
        <div class="status-icon">${p.status==='approved'?icon('check'):p.status==='rejected'?'مرفوض':'قيد المراجعة'}</div></div>`).join('') : emptyState('لا توجد مدفوعات بعد','');
  } else if (tab==='profile'){
    panel.innerHTML = `
      <div class="field"><label>الاسم</label><input type="text" id="dpName" value="${escapeHtml(session.user.name||'')}"></div>
      <div class="field"><label>البريد الإلكتروني</label><input type="email" value="${escapeHtml(session.user.email||'')}" disabled></div>
      <div class="field"><label>رقم الهاتف / الواتساب</label><input type="tel" id="dpPhone" value="${escapeHtml(session.user.phone||'')}"></div>
      <button class="btn btn-primary" id="saveProfileBtn">حفظ التغييرات</button>
      <button class="btn btn-ghost" id="logoutBtn" style="margin-top:10px;">تسجيل الخروج</button>`;
    document.getElementById('saveProfileBtn').addEventListener('click', async ()=>{
      const btn = document.getElementById('saveProfileBtn');
      const patch = {
        full_name: document.getElementById('dpName').value.trim() || session.user.name,
        phone: document.getElementById('dpPhone').value.trim(),
      };
      btn.textContent = '...جارٍ الحفظ'; btn.disabled = true;
      try {
        if (session.user?.uid) await DB.update('Users', session.user.uid, patch);
        session.user.name = patch.full_name; session.user.phone = patch.phone;
        renderNavForUser(); toast('تم حفظ التغييرات');
      } catch(e){ toast(dbFriendlyError(e)); }
      finally { btn.textContent = 'حفظ التغييرات'; btn.disabled = false; }
    });
    document.getElementById('logoutBtn').addEventListener('click', async ()=>{
      try { await fbAuth.signOut(); } catch(e){ console.error(e); }
      session.user = null; _watermarkBuilt = false; renderNavForUser(); toast('تم تسجيل الخروج'); navigate('');
    });
  }
}

