function initCookieConsent(){
  const bar = document.getElementById('cookieBar');
  let alreadyAccepted = false;
  try { alreadyAccepted = localStorage.getItem('raqeem_cookie_consent') === 'accepted'; }
  catch(e){ /* localStorage may be blocked in some embedded previews — default to showing the banner */ }
  if (!alreadyAccepted) setTimeout(() => bar.classList.add('show'), 600);
  document.getElementById('cookieAcceptBtn').addEventListener('click', () => {
    bar.classList.remove('show');
    try { localStorage.setItem('raqeem_cookie_consent', 'accepted'); } catch(e){ console.error(e); }
  });
}

