/* =====================================================================
   PWA — manifest + service worker built in-memory (no separate files
   needed). Both are generated as Blobs and linked via object URLs, so this
   single index.html is enough for "Add to Home Screen" / "Install app".
   ===================================================================== */
(function setupPWA(){
  try {
    const manifest = {
      name: 'سرمد | Sarmad',
      short_name: 'سرمد',
      description: 'منصة تعلّم برمجة متكاملة — مسارات برمجية متسلسلة، اختبارات، وشهادات موثّقة',
      start_url: location.pathname,
      scope: location.pathname.replace(/[^/]*$/, ''),
      id: 'raqeem-app',
      display: 'standalone',
      orientation: 'portrait',
      background_color: '#FFFFFF',
      theme_color: '#155FDB',
      dir: 'rtl',
      lang: 'ar',
      categories: ['education', 'lifestyle'],
      icons: [
        { src: BRAND_ICON_192, sizes: '192x192', type: 'image/png', purpose: 'any' },
        { src: BRAND_ICON_512, sizes: '512x512', type: 'image/png', purpose: 'any' },
        { src: BRAND_ICON_512, sizes: '512x512', type: 'image/png', purpose: 'maskable' },
      ],
    };
    const manifestBlob = new Blob([JSON.stringify(manifest)], { type: 'application/manifest+json' });
    const manifestLink = document.createElement('link');
    manifestLink.rel = 'manifest';
    manifestLink.href = URL.createObjectURL(manifestBlob);
    document.head.appendChild(manifestLink);

    if ('serviceWorker' in navigator) {
      // Browsers reject navigator.serviceWorker.register() on a blob: URL
      // by spec (Chrome/Firefox both throw "URL protocol not supported") —
      // this is the one PWA piece that genuinely can't be inlined into a
      // single HTML file. sw.js must stay as a real file next to
      // index.html; everything else (manifest, icons, theme) is merged in.
      window.addEventListener('load', () => {
        navigator.serviceWorker.register('sw.js').catch(err => console.error('SW registration failed:', err));
      });
    }
  } catch(e){ console.error('PWA setup failed:', e); }
})();
